// Explicit index filenames keep navigation working when pages are opened via file:// as well as Apache.
$iterator=new RecursiveIteratorIterator(new RecursiveDirectoryIterator($root,FilesystemIterator::SKIP_DOTS));
foreach($iterator as $file){
    if($file->getExtension()!=='html'||str_contains($file->getPathname(),DIRECTORY_SEPARATOR.'.git'.DIRECTORY_SEPARATOR)){continue;}
    $content=file_get_contents($file->getPathname());
    $content=preg_replace('~href="((?:\.\.?/)+)([^"?#]*?)/"~','href="$1$2/index.html"',$content);
    $content=preg_replace('~href="((?:\.\.?/)+)"~','href="$1index.html"',$content);
    file_put_contents($file->getPathname(),$content);
}
